{"cmd":"python3 - <<'PY'
from scapy.all import PcapReader, IP, IPv6, TCP, UDP
from collections import defaultdict

pcap_path='/root/packets.pcap'

src_to_dstports = defaultdict(set)

with PcapReader(pcap_path) as pcap:
    for pkt in pcap:
        if IP in pkt:
            src = pkt[IP].src
            if TCP in pkt:
                dport = int(pkt[TCP].dport)
            elif UDP in pkt:
                dport = int(pkt[UDP].dport)
            else:
                continue
            src_to_dstports[src].add(dport)
        elif IPv6 in pkt:
            src = pkt[IPv6].src
            if TCP in pkt:
                dport = int(pkt[TCP].dport)
            elif UDP in pkt:
                dport = int(pkt[UDP].dport)
            else:
                continue
            src_to_dstports[src].add(dport)

max_src = None
max_ports = 0
for src, ports in src_to_dstports.items():
    if len(ports) > max_ports:
        max_ports = len(ports)
        max_src = src

print('max unique dst ports by src', max_src, max_ports)

# maybe also unique dst IPs per src
src_to_dsts = defaultdict(set)
with PcapReader(pcap_path) as pcap:
    for pkt in pcap:
        if IP in pkt:
            src = pkt[IP].src
            dst = pkt[IP].dst
        elif IPv6 in pkt:
            src = pkt[IPv6].src
            dst = pkt[IPv6].dst
        else:
            continue
        src_to_dsts[src].add(dst)

max_dst = None
max_dsts = 0
for src, dsts in src_to_dsts.items():
    if len(dsts) > max_dsts:
        max_dsts = len(dsts)
        max_dst = src

print('max unique dst ips by src', max_dst, max_dsts)

# top 5 sources by dst ports count
print('top5 srcs by dst ports count:')
for src, ports in sorted(src_to_dstports.items(), key=lambda x: len(x[1]), reverse=True)[:5]:
    print(src, len(ports))
